pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Basic residual metrics
    let residual = post_residual as f64;
    let ratio = residual / bin_capacity as f64;          // 0..1
    let efficiency = 1.0 - ratio;                       // higher is better

    // Base cost – linear residual + quadratic penalty for large leftover
    let mut score = residual * 0.35 + ratio.powi(2) * 12.0;

    // Penalise bins whose residual is above the stream mean
    if residual > mean_residual {
        score += ((residual - mean_residual) / bin_capacity as f64).powi(2) * 5.0;
    }

    // Stronger penalty for keeping many bins open
    score += (open_bins_count as f64).sqrt() * 0.30;

    // Reward bins that could also take this item
    score -= (fitting_bins_count as f64).sqrt() * 0.05;

    // Next‑item fit check – add a fixed penalty if it doesn't fit
    if next_item_size > post_residual {
        score += 8.0;
    }

    // New‑bin handling – extra cost when many bins could fit, but
    // reward when the next item is large enough to justify a fresh bin.
    if bin_residual == bin_capacity {
        score += (fitting_bins_count as f64).sqrt() * 0.28;
        if next_item_size as f64 > 0.80 * bin_capacity as f64 {
            score -= 5.0;
        }
    }

    // Scale with stream progress – a mild diminishing penalty
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 + progress * 0.07;

    // Blend with residual weighted by packing efficiency
    score = score * 0.70 + residual * 0.30 * efficiency;

    score
}

